import React, { useState, useEffect } from 'react';

import { useNavigate } from 'react-router-dom';

import api from "../config/api";

import { handleError, handleSuccess } from '../utils';

import { ToastContainer } from 'react-toastify';

import SectionHeading from '../components/SectionHeading';

import PlanBadge from '../components/PlanBadge';

import "../styles/Plans.css";



let qrcode1 = null;

let upiImg = null;

try {

  qrcode1 = require("../Assets/qrCode.jpg");

} catch {

  qrcode1 = null;

}

try {

  upiImg = require("../Assets/upiImg.png");

} catch {

  upiImg = null;

}



const PLAN_ROWS = [

  { name: 'Rapid', balance: '₹10,000', cost: '₹1,000', lifecycle: 'One Time' },

  { name: 'Evolution', balance: '₹50,000', cost: '₹5,000', lifecycle: 'Unlimited' },

  { name: 'Prime', balance: '₹1,00,000', cost: '₹10,000', lifecycle: 'Unlimited' },

];



function Plans() {

    const [selectedPlan, setSelectedPlan] = useState(null);

    const [showPopup, setShowPopup] = useState(false);

    const [hasBoughtRapid, setHasBoughtRapid] = useState(false);

    const [currentPlan, setCurrentPlan] = useState(null);

    const navigate = useNavigate();



    useEffect(() => {

        const token = localStorage.getItem('token');



        if (!token) {

            navigate('/login');

            return;

        }



        const fetchUserPlanStatus = async () => {

            try {

                const response = await api.get('/api/plans/user-plan/me');

                if (response.data) {

                    setHasBoughtRapid(response.data.hasBoughtRapidPlan);

                    setCurrentPlan(response.data.plan);

                }

            } catch (error) {

                console.error("Error fetching user plan status:", error);

            }

        };



        fetchUserPlanStatus();

    }, [navigate]);



    const buyPlan = (plan) => {

        if (plan === 'Rapid' && hasBoughtRapid) {

            alert('You cannot buy the Rapid plan again!');

        } else {

            setSelectedPlan(plan);

            setShowPopup(true);

        }

    };



    const handlePayment = async () => {

        const mobile = localStorage.getItem('userMobile') || '';



        if (!/^[0-9]{10}$/.test(mobile)) {

            handleError('A valid 10-digit mobile number is required before accessing the watchlist.');

            setShowPopup(false);

            navigate('/signup');

            return;

        }



        try {

            const response = await api.post('/api/plans/purchase', { plan: selectedPlan });



            if (response.status === 200) {

                handleSuccess(response.data.msg);

                setShowPopup(false);

                setCurrentPlan(selectedPlan);

                if (selectedPlan === 'Rapid') {

                    setHasBoughtRapid(true);

                }

                navigate('/watchlist1');

            }

        } catch (error) {

            handleError(error.response?.data?.msg || 'Welcome to LeverageX Team ✨');

            navigate('/watchlist1');

        }

    };



    return (

        <div className="plans-container">

            <div className="page-hero">

                <SectionHeading

                    kicker="Membership"

                    title="Membership Plans"

                    subtitle={currentPlan ? `Your active plan: ${currentPlan}` : 'Select a plan to unlock your funded watchlist and trading balance.'}

                />

            </div>



            <div className="plans-table-wrapper">

                <table className="plans-table">

                    <thead>

                        <tr>

                            <th>Plan</th>

                            <th>Trading Balance</th>

                            <th>Minimum Trading Days</th>

                            <th>Margin</th>

                            <th>Plan Cost</th>

                            <th>Life Cycle</th>

                        </tr>

                    </thead>

                    <tbody className="membership-plan">

                        {PLAN_ROWS.map((plan) => (

                            <tr key={plan.name}>

                                <td className="plan-action-cell">

                                    <div className="plan-cell-stack">

                                        <PlanBadge plan={plan.name} size="small" />

                                        <button

                                            type="button"

                                            className={hasBoughtRapid && plan.name === 'Rapid' ? 'disabled-btn' : 'buy-now-btn'}

                                            onClick={() => buyPlan(plan.name)}

                                            disabled={hasBoughtRapid && plan.name === 'Rapid'}

                                        >

                                            {hasBoughtRapid && plan.name === 'Rapid' ? 'Plan Used' : 'Buy Now'}

                                        </button>

                                    </div>

                                </td>

                                <td>{plan.balance}</td>

                                <td>5 Days</td>

                                <td>10X</td>

                                <td>{plan.cost}</td>

                                <td>{plan.lifecycle}</td>

                            </tr>

                        ))}

                    </tbody>

                </table>

            </div>



            <section className="section-plan">

                <SectionHeading

                    kicker="Details"

                    title="Choose your plan"

                    subtitle="Every tier is designed for a different stage of your trading journey."

                />

                <div className="plan-amt">

                    <div className="amt funding-card">

                        <PlanBadge plan="Rapid" size="small" />

                        <h3>Rapid Plan (₹ 1,000)</h3>

                        <p>Perfect for traders who want to start small and fast. For just Rs 1,000, you can join our Rapid Plan and start trading with leveraged capital.</p>

                    </div>

                    <div className="amt funding-card featured-plan-card">

                        <PlanBadge plan="Evolution" size="small" />

                        <h3>Evolution Plan (₹ 5,000)</h3>

                        <p>Designed for those who are ready to take their trading to the next level with more capital and more flexibility.</p>

                    </div>

                    <div className="amt funding-card">

                        <PlanBadge plan="Prime" size="small" />

                        <h3>Prime Plan (₹ 10,000)</h3>

                        <p>For serious traders aiming to trade with large amounts of capital and maximize their profit potential.</p>

                    </div>

                </div>

            </section>



            {showPopup && (

                <div className="popup-overlay">

                    <div className="popup qr-background popup-responsive">

                        <h2 className="qr-h2">Pay for {selectedPlan}</h2>

                        <p className="qr-p">Total: ₹ {selectedPlan === 'Rapid' ? '1000' : selectedPlan === 'Evolution' ? '5000' : '10,000'} /-</p>

                        <p className="pay-here">Pay Here</p>

                        {qrcode1 ? (

                          <img src={qrcode1} alt="" className="qr-image" />

                        ) : (

                          <p className="qr-p">QR code image unavailable — use UPI ID below</p>

                        )}

                        <p className="qr-p qr-pq">leveragexfundx-4@okicici</p>
                         <p className="qr-p qr-pq">leveragxcradit@ptyes</p>

                        {upiImg && <img src={upiImg} alt="" className="upi-img" />}

                        <input placeholder="Enter Txn Number" type="number" className="input-num" required />

                        <div className="popup-actions">

                            <button type="button" className="done-btn done-bttn" onClick={handlePayment}>Done</button>

                            <button type="button" className="cancel-btn" onClick={() => setShowPopup(false)}>X</button>

                        </div>

                    </div>

                </div>

            )}

            <ToastContainer />

        </div>

    );

}



export default Plans;

